SELECT
    d.*,t.unit_id
FROM
    jc_fund_filling_detail d,
    jc_fund_filling t
WHERE
    d.FILLING_ID = t.FILLING_ID
AND t.FILL_YEAR = #{fillYear}
and t.FILL_TYPE = #{fillType}
AND t.unit_id = (
    SELECT
        u.unit_id
